    protected bool $enabledAssigned = false;

    public function getEnabledOrDefault(?ThemeEnabledVO $enabled): ?ThemeEnabledVO
    {
        return $this->enabledAssigned ? ($this->enabled !== null ? ThemeEnabledVO::from($this->enabled) : null) : $enabled;
    }
    public function enabled(ThemeEnabledVO|bool|null $enabled): static
    {
        $this->enabled = $enabled;
        $this->enabledAssigned = true;
        return $this;
    }
    public function isEnabled(): ?bool
    {
        return $this->enabled instanceof ThemeEnabledVO ? $this->enabled->value() : $this->enabled;
    }
    public function isEnabledAssigned(): bool
    {
        return $this->enabledAssigned;
    }
    public function writeEnabledTo(mixed $att): void
    {
        if ($this->enabledAssigned) {
            $att->enabled($this->enabled);
        }
    }
    public function readEnabledFrom(mixed $att): void
    {
        if ($att->isEnabledAssigned()) {
            $enabled = $att->isEnabled();
            $this->enabled($enabled);
        }
    }
    public function unsetEnabled(): static
    {
        $this->enabledAssigned = false;
        return $this;
    }
    protected function withDefaultEnabled(): void
    {
        if ($this->enabled === null) {
            $this->enabled = true;
        }
    }
    protected function withAssertedEnabledRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->enabledAssigned = $this->enabledAssigned) {
            $value->enabled = ThemeEnabledVO::tryFrom($this->enabled, $errorsList);
        }
    }
}
